<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { http, ApiError } from '@/api/http'
import type { AuthUser } from '@/stores/auth'
const rows = ref<AuthUser[]>([]), roles = ref<{ id: string; name: string }[]>([]), loading = ref(false), saving = ref(false), visible = ref(false), error = ref(''), editing = ref('')
const form = reactive({ username: '', display_name: '', role_id: '', password: '', status: 'active' })
async function load() { loading.value = true; try { const [u, r] = await Promise.all([http.get('/auth/users'), http.get('/auth/roles')]); rows.value = u.data.items; roles.value = r.data.items; error.value = '' } catch (err) { error.value = err instanceof ApiError ? err.message : '读取失败' } finally { loading.value = false } }
function open(user?: AuthUser) { editing.value = user?.id || ''; Object.assign(form, { username: user?.username || '', display_name: user?.display_name || '', role_id: user?.role_id || roles.value.find(r => r.name === '招聘人员')?.id || '', password: '', status: user?.status || 'active' }); visible.value = true }
async function save() {
  if (!form.display_name.trim() || !form.role_id || (!editing.value && !/^[A-Za-z0-9_.-]{3,64}$/.test(form.username))) { ElMessage.warning('请填写用户名、姓名和角色'); return }
  if ((!editing.value || form.password) && (form.password.length < 1 || form.password.length > 128)) { ElMessage.warning('密码须为 1–128 位'); return }
  saving.value = true
  try { const data = { display_name: form.display_name.trim(), role_id: Number(form.role_id), ...(form.password ? { password: form.password } : {}), ...(editing.value ? { status: form.status } : { username: form.username }) }; if (editing.value) await http.patch(`/auth/users/${editing.value}`, data); else await http.post('/auth/users', data); visible.value = false; form.password = ''; ElMessage.success('用户已保存；修改后的用户需重新登录'); await load() } catch (err) { ElMessage.error(err instanceof ApiError ? err.message : '保存失败') } finally { saving.value = false }
}
async function revoke(user: AuthUser) { try { await ElMessageBox.confirm(`确认让 ${user.display_name} 的所有设备退出登录？`, '吊销会话'); await http.post(`/auth/users/${user.id}/revoke-sessions`); ElMessage.success('已吊销登录会话') } catch (err) { if (err instanceof ApiError) ElMessage.error(err.message) } }
onMounted(load)
</script>
<template><div><div class="users-heading"><div><h1>用户管理</h1><p>创建账号、分配角色、停用用户或重置密码。用户首次登录须修改初始密码。</p></div><el-button type="primary" :disabled="!!error || loading" @click="open()">新建用户</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"><el-button text @click="load">重新加载</el-button></el-alert><el-table :data="rows" v-loading="loading"><el-table-column label="用户名" prop="username" min-width="130" /><el-table-column label="姓名" prop="display_name" min-width="130" /><el-table-column label="角色" prop="role_name" width="120" /><el-table-column label="状态" width="100"><template #default="{ row }"><el-tag :type="row.status === 'active' ? 'success' : 'info'">{{ row.status === 'active' ? '启用' : '停用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="230"><template #default="{ row }"><el-button text type="primary" @click="open(row)">编辑 / 重置密码</el-button><el-button text @click="revoke(row)">吊销会话</el-button></template></el-table-column></el-table><el-dialog v-model="visible" :title="editing ? '编辑用户' : '新建用户'" width="min(520px, 94vw)" :close-on-click-modal="false" :close-on-press-escape="!saving" :show-close="!saving" @closed="form.password = ''"><el-form label-position="top" :disabled="saving"><el-form-item label="用户名"><el-input v-model="form.username" aria-label="用户名" :disabled="!!editing" maxlength="64" /></el-form-item><el-form-item label="显示姓名"><el-input v-model="form.display_name" aria-label="显示姓名" maxlength="128" /></el-form-item><el-form-item label="角色"><el-select v-model="form.role_id" aria-label="角色"><el-option v-for="role in roles" :key="role.id" :value="role.id" :label="role.name" /></el-select></el-form-item><el-form-item v-if="editing" label="状态"><el-radio-group v-model="form.status"><el-radio value="active">启用</el-radio><el-radio value="disabled">停用</el-radio></el-radio-group></el-form-item><el-form-item :label="editing ? '重置密码（留空则不修改）' : '初始密码（不能为空）'"><el-input v-model="form.password" aria-label="设置密码" type="password" show-password maxlength="128" autocomplete="new-password" /></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="visible = false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存用户</el-button></template></el-dialog></div></template>
<style scoped>.users-heading { display: flex; justify-content: space-between; gap: 20px; align-items: center; margin-bottom: 20px; }h1 { font-size: 22px; }p { color: #8792a2; font-size: 13px; }</style>
